        "definition": "• 넓은 의미로 분산매가 분산상에 퍼져있는 현상을 말하며, 기체·액체·고체 등 하나의 상에 다른 상이 균일하게 혼합되는 상태\n• 액체가 액체 속에 분산되는 경우를 유화, 기체가 액체 속에 분산되는 경우를 거품이라고 함\n• 분산에 영향을 미치는 요인: 안료의 종류, 분산질의 종류, 분산질의 형상, 분산질의 입도(입자의 크기)\n• 적용 제품: 고체-액체 분산계는 파운데이션, 비비 크림, 메이크업 베이스, 마스카라, 아이라이너, 립스틱 등\n• 분산제 종류: 벤토나이트, 폴리하이드로시스테아릭애씨드 등",
