        "definition": "• 피부의 거칠음 방지\n• 피부 청정 및 피부 보호\n• 피부에 수분 공급과 유연 작용\n• 피부에 수렴 효과와 탄력 증진\n예) 화장수, 유액(로션), 에센스(세럼), 크림류, 팩 등",
