        "term": "기능성 화장품",
        "definition": "• 피부에 멜라닌색소가 침착하는 것을 방지하여 기미·주근깨 등의 생성을 억제함으로써 피부의 미백에 도움을 줌\n• 피부에 침착된 멜라닌색소의 색을 옅게 하여 피부의 미백에 도움을 줌\n• 피부에 탄력을 주어 피부의 주름을 완화 또는 개선함\n• 강한 햇볕을 방지하여 피부를 곱게 태워줌\n• 자외선을 차단 또는 산란시켜 자외선으로부터 피부를 보호함\n• 모발의 색상을 변화(탈염·탈색 포함)시킴 (단, 일시적으로 모발의 색상을 변화시키는 제품은 제외함)\n• 체모를 제거하는 기능을 함 (단, 물리적으로 체모를 제거하는 제품은 제외함)\n• 탈모 증상의 완화에 도움을 줌 (단, 코팅 등 물리적으로 모발을 굵어 보이게 하는 제품은 제외함)\n• 여드름성 피부 완화 (인체 세정용 제품류로 한정함)\n• 피부장벽(피부의 가장 바깥쪽에 존재하는 각질층의 표피)의 기능을 회복하여 가려움 등의 개선에 도움을 줌\n• 튼살로 인한 붉은 선을 옅게 하는 데 도움을 줌",
