        "definition": "• 세정용: 모발과 두피의 피지, 땀, 각질 등 오염 물질을 제거하여 청결하고 건강하게 유지시킴\n예) 샴푸, 린스\n• 정발제: 모발을 물리적으로 원하는 형태로 만들어 주고 형태를 고정시킴\n예) 헤어 오일, 포마드, 헤어 크림 및 로션, 헤어 스프레이, 헤어 젤, 헤어 왁스 등\n• 헤어 트리트먼트제: 모발 손상을 방지하고 손상된 모발을 회복하기 위해 사용하여 오일을 함유하여 살균, 청량, 쾌적함을 부여하고 비듬, 가려움을 제거하기 위해 사용함\n• 양모제: 30~70% 에탄올을 함유하여 살균, 청량, 쾌적함을 부여하고 탈모 증상 완화에 도움을 줌\n• 퍼머넌트 웨이브 용제: 모발 케라틴 속의 시스틴 결합(-S-S-)을 환원제로 부분적으로 절단한 다음 산화제로 재결합하여 모발에 웨이브를 만들어 줌\n예) 제1제 - 환원제: 치오글라이콜릭애씨드, 시스테인 / 알칼리제: 암모니아, 모노에탄올아민\n　　제2제 - 산화제: 브롬산나트륨, 과산화수소\n• 염모제: 모발의 색상을 변화시킴\n예) 일시적 염모제, 반영구 염모제, 영구 염모제, 헤어 블리치\n• 제모제: 손, 발이나 겨드랑이, 다리 등의 털을 제거함\n예) 물리적 제모제: 제모왁스, 제모 젤·테이프 / 화학적 제모제: 제모 크림",
