        "category": "5. 화장품 사용할 때의 주의사항",
        "term": "퍼머넌트 웨이브 제품 및 헤어 스트레이트너 제품 (기출)",
        "definition": "• 두피·얼굴·눈·목·손 등에 약액이 묻지 않도록 유의하고, 얼굴 등에 약액이 묻었을 때에는 즉시 물로 씻어낼 것\n• 특이체질, 생리 또는 출산 전후이거나 질환이 있는 사람 등은 사용을 피할 것\n• 머리카락의 손상 등을 피하기 위하여 용법·용량을 지켜야 하며, 가능하면 일부에 시험적으로 사용하여 볼 것\n• 섭씨 15도 이하의 어두운 장소에 보존하고, 색이 변하거나 침전된 경우에는 사용하지 말 것\n• 개봉한 제품은 7일 이내에 사용할 것(에어로졸 제품이나 사용 중 공기유입이 차단되는 용기는 표시하지 아니함)\n• 제2단계 퍼머액 중 그 주성분이 과산화수소인 제품은 검은 머리카락이 갈색으로 변할 수 있으므로 유의하여 사용할 것",
