        "definition": "• 정해진 용법과 용량 준수\n• 3세 이하 영유아, 임신 중, 분만 직전 여성의 외음부 주위에는 사용하지 말 것\n• 외음부에만 사용하며, 질 내에 사용하지 말 것\n• 프로필렌글리콜을 함유하고 있으므로 이 성분에 과민하거나 알레르기 병력이 있는 사람은 신중히 사용할 것(프로필렌글리콜 함유 제품만 표시함)",
