        "question": "• 식품의약품안전처장은 다음 각 호의 어느 하나에 해당하는 경우에는 해당 영업자에 대하여 그 사실의 공표를 명할 수 있음\n  - 위해화장품 회수에 따른 회수계획을 보고받은 때\n  - 위해화장품의 공표에 따른 회수계획을 보고받은 때\n• 식품의약품안전처장은 국민 건강에 대한 위해를 방지하기 위하여 위해가 발생하였거나 발생할 우려가 있는 직접구매 해외화장품에 관한 정보를 공표할 수 있음\n• 공표의 방법·절차 등에 필요한 사항은 총리령으로 정함\n• 공표명령을 받은 영업자는 지체 없이 발생 사실 또는 아래 사항을 전국을 보급지역으로 하는  [ 빈칸 ]  이상의 일반일간신문 및 해당 영업자의 인터넷 홈페이지에 게재해야 함\n• 식품의약품안전처의 인터넷 홈페이지에 게재 요청(단, 위해성 등급이 다등급의 경우 일반일간신문에의 게재 생략 가능)\n  - 화장품을 회수한다는 내용의 표제\n  - 제품명\n  - 회수 대상 화장품의 제조번호\n  - 사용기한 또는 개봉 후 사용기간\n  - 회수 사유\n  - 회수 방법\n  - 회수하는 영업자의 명칭\n  - 회수하는 영업자의 전화번호, 주소, 그 밖에 회수에 필요한 사항",
