        "definition": "화장품 안전관리를 위해 화장품업 단체 또는 등록한 소비자단체의 임직원 중 해당 단체의 장이 추천한 사람이나 화장품 안전관리에 관한 지식이 있는 사람을 위촉 / 책임판매관리자의 자격 기준 중 어느 하나에 해당하는 사람 / 소비자화장품감시원을 대상으로 한 교육 과정을 마친 사람",
