        "definition": "• 공공기관의 개인정보 처리업무 방해를 목적으로 개인정보를 변경, 말소하여 업무 수행에 지장을 초래한 자\n• 거짓이나 그 외 부정한 수단, 방법으로 다른 사람이 처리하고 있는 개인정보를 취득하여 영리 또는 부정한 목적으로 제3자에게 제공, 알선, 교사한 자",
        "isKey": false
