        "definition": "• 영상정보처리기기의 설치 목적과 다른 목적으로 영상정보처리기기를 임의로 조작하거나 녹음한 자\n• 거짓이나 부정한 수단, 방법으로 개인정보를 취득하거나 사정을 알면서 영리 또는 부정한 목적으로 개인정보를 제공받은 자\n• 직무상 알게 된 비밀을 누설하거나 목적 외에 이용한 자",
        "isKey": false
