        "question": "• 선정된 측정 위치마다 세균용 배지와 진균용 배지를 1개씩 놓고 배양접시의 뚜껑을 열어 배지에 낙하균이 떨어지도록 함\n• 위치별로 정해진 노출 시간이 지나면, 배양접시의 뚜껑을 닫아 배양기에서 배양함. 일반적으로 세균용 배지는 30~35℃,  [ 빈칸 ]  이상, 진균용 배지는 20~25℃, 5일 이상 배양함. 배양 중에 확산균의 증식에 의해 균수를 측정할 수 없는 경우가 있으므로 매일 관찰하고 균수의 변동을 기록함\n• 배양 종료 후 세균 및 진균의 평판마다 집락수를 측정하고, 사용한 배양접시 수로 나누어 평균 집락수를 구하고 단위시간당 집락수를 산출하여 균수로 함",
