        "definition": "• 판매업 신고를 하지 않은 자가 판매한 맞춤형화장품\n• 맞춤형화장품조제관리사를 두지 않고 판매한 맞춤형화장품\n• 의약품으로 잘못 인식할 우려가 있게 기재·표시한 화장품\n• 판매 목적이 아닌 제품의 홍보·판매 촉진을 위해 미리 소비자가 시험·사용하도록 제조 또는 수입된 화장품",
