        "term": "제8조의3\n맞춤형화장품 판매업의 변경신고",
        "definition": "• 맞춤형화장품판매업자가 다음의 사항을 변경하는 경우에는 변경신고를 해야 함\n  - 맞춤형화장품판매업자를 변경하는 경우\n  - 맞춤형화장품판매업소의 상호 또는 소재지를 변경하는 경우\n  - 맞춤형화장품조제관리사를 변경하는 경우\n• 신고기한: 변경이 있는 날부터 30일 이내에 관할 지방식품의약품안전청장에게 신고\n• 행정기관 처리기한: 변경신고서(전자문서 포함) 접수 후 10일 이내 처리 (단, 조제관리사 변경신고는 7일 이내 처리)",
