        "term": "1차 포장 필수 기재사항\n(단, 소비자가 화장품의 1차 포장을 제거하고 사용하는 고형비누 등 총리령으로 정하는 화장품의 경우에는 그러하지 아니함)",
        "definition": "• 화장품의 명칭\n• 영업자(화장품제조업자, 화장품책임판매업자, 맞춤형화장품판매업자)의 상호\n• 제조번호(식별번호)\n• 사용기한 또는 개봉 후 사용기간(개봉 후 사용기간의 경우 제조연월일 병기)",
        "isKey": false
