        "term": "재검토기한",
        "definition": "식품의약품안전처장은 「훈령·예규 등의 발령 및 관리에 관한 규정」에 따라 이 고시에 대하여 2016년 7월 1일 기준으로 매 3년이 되는 시점(매 3년째의 6월 30일까지를 말함)마다 그 타당성을 검토하여 개선 등의 조치를 해야 함",
