        "definition": "• 검화가, 굴절률, 비선광도, 비점, 비중, 산가, 수산기가, 알코올수, 에스테르가, 요오드가, 융점, 응고점, 점도, pH, 흡광도 등 물리·화학적 방법으로 측정되는 정수 기재\n• 원료성분의 본질 및 순도를 나타내기 위해 작성하며, 「기능성화장품 기준 및 시험 방법」의 VI. 일반시험법에 따름",
        "isKey": false
