        "term": "순도시험",
        "definition": "• 색, 냄새, 용해 상태, 액성, 산, 알칼리, 염화물, 황산염, 중금속, 비소, 황산에 대한 정색물, 동, 석, 수은, 아연, 알루미늄, 철, 알칼리토류금속, 일반이물(제조공정으로부터 혼입, 잔류, 생성 또는 첨가될 수 있는 불순물), 유연 물질 및 분해생성물, 잔류용매 중 필요한 항목 설정\n• 용해 상태는 원료의 순도 파악이 가능한 경우 설정",
