        "definition": "• 「기능성화장품 기준 및 시험 방법」 수재 이외의 표준품은 사용목적에 맞는 규격을 설정하며, 수재 이외의 시약·시액은 그 조제법 기재\n• 표준품은 필요에 따라 정제법 기재\n• 정량용 표준품은 원칙적으로 순도시험에 따라 불순물을 규제한 절대량을 측정할 수 있는 시험 방법으로 함량 측정\n• 표준품의 함량은 99.0% 이상으로 함",
