        "question": "• 식품의약품안전처장은 매년 1회 이상 자격시험 실시\n• 자격시험 시행계획은 시험 실시  [ 빈칸 ]  전까지 식약처 인터넷 홈페이지에 공고\n• 전 과목 총점의 60% 이상, 매 과목 만점의 40% 이상 득점 시 합격\n• 시험위원은 시험과목에 대한 전문지식을 갖추거나 화장품에 관한 업무 경험이 풍부한 사람으로 위촉",
