        "question": "• 자격증 발급 신청 시 다음 각 호의 서류를 첨부하여 식품의약품안전처장에게 제출\n  - 마약류의 중독자에 해당되지 않음을 증명하는 최근  [ 빈칸 ]  이내의 의사의 진단서\n  - 맞춤형화장품조제관리사 결격사유인 정신질환자이지만, 전문의가 맞춤형화장품조제관리사로서 적합하다고 인정하는 경우 최근  [ 빈칸 ]  이내의 전문의의 진단서\n• 자격증을 잃어버리거나 못 쓰게 된 경우\n  - 자격증을 잃어버린 경우: 분실 사유서\n  - 자격증을 못 쓰게 된 경우: 자격증 원본",
