        "question": "• 최초 교육: 종사한 날부터  [ 빈칸 ]  이내(단, 자격시험에 합격한 날이 종사한 날 이전 1년 이내이면 최초 교육을 받은 것으로 봄)\n• 보수 교육: 최초 교육을 받은 날을 기준으로 매년 1회(단, 자격시험에 합격한 날이 종사한 날 이전 1년 이내여서 교육을 생략한 경우, 자격시험에 합격한 날부터 1년이 되는 날을 기준으로 매년 1회 보수 교육을 받아야 함)\n• 4시간 이상 8시간 이하로 참여\n• 교육실시기관: 대한화장품협회, 한국의약품수출입협회, 대한화장품산업연구원",
        "answer": "6개월",
